<div class="form-grid"><div class="field"><label>Student</label><select class="select" name="student_id" required><option value="">Select student</option><?php $__currentLoopData = $students; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $student): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($student->id); ?>" <?php if(old('student_id',$attendance->student_id ?? '') == $student->id): echo 'selected'; endif; ?>><?php echo e($student->student_code); ?> — <?php echo e($student->first_name); ?> <?php echo e($student->last_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="field"><label>Date</label><input class="input" type="date" name="attendance_date" value="<?php echo e(old('attendance_date',isset($attendance) ? $attendance->attendance_date->format('Y-m-d') : now()->toDateString())); ?>" required></div><div class="field"><label>Status</label><select class="select" name="status" required><?php $__currentLoopData = ['Present','Absent','Late','Excused']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $status): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($status); ?>" <?php if(old('status',$attendance->status ?? '') === $status): echo 'selected'; endif; ?>><?php echo e($status); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="field"><label>Check-in Time</label><input class="input" type="time" name="check_in" value="<?php echo e(old('check_in',$attendance->check_in ?? '')); ?>"></div><div class="field full"><label>Note</label><input class="input" name="note" value="<?php echo e(old('note',$attendance->note ?? '')); ?>" placeholder="Optional note"></div></div><div class="form-actions"><a class="btn btn-light" href="<?php echo e(route('attendance.index')); ?>">Cancel</a><button class="btn btn-primary"><?php echo e($buttonText); ?></button></div><?php /**PATH C:\laragon\www\attendance_management_laravel13\resources\views/attendance/_form.blade.php ENDPATH**/ ?>